// Wizard's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/wizard.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// The page shown, counted from zero among the WizardPage children. A write moves there at once and raises page_changed, without page_changing; past the last page throws std::invalid_argument (zero is always accepted).
template <typename Declaring>
struct WizardCurrentPageCapability {
    PropertyCell<std::uint32_t, WizardCurrentPageCapability<Declaring>> current_page{0U};

    static void assign(WizardCurrentPageCapability& capability, std::uint32_t incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.current_page), incoming);
        if (!capability.current_page.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.current_page));
    }
};

// Whether the step indicator shows above the page, naming every page by its title.
template <typename Declaring>
struct WizardShowStepIndicatorCapability {
    PropertyCell<bool, WizardShowStepIndicatorCapability<Declaring>> show_step_indicator{true};

    static void assign(WizardShowStepIndicatorCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.show_step_indicator), incoming);
        if (!capability.show_step_indicator.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.show_step_indicator));
    }
};

