// Every Wizard capability, in the order the declaring class takes them.
template <typename Declaring>
struct WizardCapabilities : public WizardCurrentPageCapability<Declaring>,
                            public WizardShowStepIndicatorCapability<Declaring>,
                            public WizardBackTextCapability<Declaring>,
                            public WizardNextTextCapability<Declaring>,
                            public WizardFinishTextCapability<Declaring>,
                            public WizardCancelTextCapability<Declaring> {};

